 static final String MODEL="gemini-cost-offline-mock",PASSWORD=UUID.randomUUID().toString();
 static final Map<String,Object> P=IsolatedStudyLogServer.properties(8104,UUID.randomUUID().toString(),new BCryptPasswordEncoder(12).encode(PASSWORD));
 @DynamicPropertySource static void properties(DynamicPropertyRegistry r){P.forEach((k,v)->r.add(k,()->v));r.add("planner.ai-cost.enabled",()->true);for(String f:List.of("daily","summary")){r.add("planner.ai-cost."+f+".approved-model",()->MODEL);r.add("planner.ai-cost."+f+".max-attempts",()->10);r.add("planner.ai-cost."+f+".max-output-tokens",()->100);}r.add("llm.model",()->MODEL);r.add("gemini.model",()->MODEL);r.add("llm.demo-mode",()->false);}
 @Autowired WebApplicationContext ctx;@Autowired JdbcTemplate jdbc;@Autowired GoalRepository goals;@Autowired SubjectRepository subjects;@Autowired StudyLogRepository logs;@Autowired AiResponseRepository responses;@Autowired AiCostProtection cost;@Autowired PlatformTransactionManager manager;@Autowired Environment env;
 MockMvc mvc;MockHttpSession session;String csrf;long a,b;HttpClient wire;IsolatedRescheduleFixture.Baseline baseline;IsolatedRescheduleFixture.Seed seed;AiResponseRecorder recorder;AtomicInteger sends;
 final ObjectMapper json=new ObjectMapper();
 @BeforeEach void setup()throws Exception{
  assertThrows(ClassNotFoundException.class,()->Class.forName("com.mysql.cj.jdbc.Driver"));assertInstanceOf(org.springframework.mock.web.MockServletContext.class,ctx.getServletContext());IsolatedStudyLogFixture.assertH2(jdbc,(String)P.get("spring.datasource.url"));
  jdbc.execute("DROP TABLE IF EXISTS ai_generation_requests");for(String t:List.of("ai_responses","study_questions","study_logs","subjects","goals","users"))jdbc.update("DELETE FROM "+t);jdbc.execute("DROP TABLE IF EXISTS study_saved_plans");jdbc.execute("DROP TABLE IF EXISTS study_schedule_settings");
  seed=IsolatedRescheduleFixture.seed((org.springframework.context.ConfigurableApplicationContext)ctx,(String)P.get("spring.datasource.url"));a=seed.goalA();b=seed.goalB();baseline=IsolatedRescheduleFixture.baseline((org.springframework.context.ConfigurableApplicationContext)ctx);
  try(var c=jdbc.getDataSource().getConnection()){ScriptUtils.executeSqlScript(c,new ClassPathResource("review/ai-cost-protection.h2.sql"));}
  sends=new AtomicInteger();wire=mock(HttpClient.class);HttpResponse<String> reply=mock(HttpResponse.class);when(reply.statusCode()).thenReturn(200);when(reply.body()).thenReturn("{\"modelVersion\":\""+MODEL+"-001\",\"usageMetadata\":{\"promptTokenCount\":11,\"candidatesTokenCount\":7,\"totalTokenCount\":18},\"candidates\":[{\"content\":{\"parts\":[{\"text\":\"[격리 Fake Wire · 실제 AI 아님] 한글 \\\"합성\\\" 답변\"}]}}]}");when(wire.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenAnswer(i->{sends.incrementAndGet();return reply;});
  var daily=ctx.getBean(LlmCoachingController.class);var summary=ctx.getBean(GeminiStudySummaryController.class);ReflectionTestUtils.setField(daily,"httpClient",wire);ReflectionTestUtils.setField(daily,"geminiApiKey","synthetic-not-a-key");ReflectionTestUtils.setField(summary,"httpClient",wire);ReflectionTestUtils.setField(summary,"geminiApiKey","synthetic-not-a-key");recorder=(AiResponseRecorder)ReflectionTestUtils.getField(daily,"responseRecorder");
  mvc=MockMvcBuilders.webAppContextSetup(ctx).apply(springSecurity()).build();var r=mvc.perform(get("/auth/csrf")).andReturn();session=(MockHttpSession)r.getRequest().getSession();csrf=tree(r).path("token").asText();assertEquals(200,mvc.perform(post("/auth/login").session(session).header("X-CSRF-TOKEN",csrf).param("username","mobile-h2-owner").param("password",PASSWORD)).andReturn().getResponse().getStatus());csrf=tree(mvc.perform(get("/auth/csrf").session(session)).andReturn()).path("token").asText();
 }
 @AfterEach void unchanged(){ReflectionTestUtils.setField(ctx.getBean(LlmCoachingController.class),"responseRecorder",recorder);assertEquals(baseline,IsolatedRescheduleFixture.baseline((org.springframework.context.ConfigurableApplicationContext)ctx));}
 JsonNode tree(MvcResult r)throws Exception{return json.readTree(r.getResponse().getContentAsByteArray());}
 String key(){return "cost_"+UUID.randomUUID();}
 Map<String,Object> body(){return Map.of("confirmPaidCall",true,"expectedModel",MODEL);}
 MvcResult generate(String path,long goal,String k)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(path).session(session).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",k).param("goalId",""+goal).contentType("application/json").content(json.writeValueAsBytes(body()))).andReturn();}
 MvcResult lookup(String f,long g,String k)throws Exception{return mvc.perform(get("/ai-generation-requests").session(session).param("feature",f).param("goalId",""+g).param("requestKey",k)).andReturn();}
 java.util.function.Supplier<Map<String,Object>> synthetic(AiCostProtection c,long g,String field){return ()->{c.beforeSend("synthetic prompt, no real transport");sends.incrementAndGet();return new LinkedHashMap<>(Map.of("goalId",g,"provider","gemini","model",MODEL,"responseModel",MODEL+"-fake","responseSource","provider","statusCode",200,field,"격리 FakeWire, 실제 AI 아님","mockResponse",true));};}
 Map<String,Object> run(AiCostProtection c,long user,String f,long g,String k){return c.execute(user,f,g,"gemini",MODEL,k,"POST",body(),synthetic(c,g,f.equals("DAILY_COACHING")?"llmResponse":"summary"));}
 int rows(){return jdbc.queryForObject("SELECT COUNT(*) FROM ai_generation_requests",Integer.class);}
 static String bodyOf(HttpRequest request)throws Exception{var out=new java.io.ByteArrayOutputStream();var done=new CompletableFuture<String>();request.bodyPublisher().orElseThrow().subscribe(new java.util.concurrent.Flow.Subscriber<java.nio.ByteBuffer>(){public void onSubscribe(java.util.concurrent.Flow.Subscription s){s.request(Long.MAX_VALUE);}public void onNext(java.nio.ByteBuffer b){byte[] a=new byte[b.remaining()];b.get(a);out.writeBytes(a);}public void onError(Throwable e){done.completeExceptionally(e);}public void onComplete(){done.complete(out.toString(java.nio.charset.StandardCharsets.UTF_8));}});return done.get(2,TimeUnit.SECONDS);}
 @Test void dailyFirstDuplicateAndHistoryUseOneWireAndOneResponse()throws Exception{String k=key();var one=generate("/llm-coaching",a,k);assertEquals(200,one.getResponse().getStatus());assertEquals("COMPLETED",tree(one).at("/costProtection/state").asText());var again=generate("/llm-coaching",a,k);assertEquals(tree(one),tree(again));assertEquals(1,sends.get());assertEquals(1,responses.count());assertEquals(1,rows());assertEquals("COMPLETED",tree(lookup("DAILY_COACHING",a,k)).path("state").asText());assertEquals(1,sends.get());}
 @Test void summaryHasIndependentDurableSnapshotNotFalseAiResponseSave()throws Exception{String k=key();var r=generate("/study-log-summary",a,k);assertEquals(200,r.getResponse().getStatus());assertTrue(tree(r).path("summary").asText().contains("격리"));assertFalse(tree(r).has("responseSaved"));assertEquals(0,responses.count());assertEquals("COMPLETED",tree(lookup("STUDY_SUMMARY",a,k)).path("state").asText());generate("/study-log-summary",a,k);assertEquals(1,sends.get());}
 @Test void differentFeatureAndKeysAreIndependent()throws Exception{String k=key();generate("/llm-coaching",a,k);generate("/study-log-summary",a,k);generate("/llm-coaching",a,key());assertEquals(3,sends.get());assertEquals(3,rows());}
 @Test void requestKeyWithOtherGoalOrBodyOrModelConflicts()throws Exception{String k=key();generate("/llm-coaching",a,k);assertEquals(409,generate("/llm-coaching",b,k).getResponse().getStatus());assertEquals(400,mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post("/llm-coaching").session(session).header("X-CSRF-TOKEN",csrf).header("Idempotency-Key",k).param("goalId",""+a).contentType("application/json").content("{\"confirmPaidCall\":true,\"expectedModel\":\"other\"}")).andReturn().getResponse().getStatus());assertEquals(1,sends.get());}
 @Test void manyConcurrentRequestsAcrossServiceInstancesReserveOnce()throws Exception{String k=key();var pool=Executors.newFixedThreadPool(6);try{var jobs=new ArrayList<Callable<Integer>>();for(int i=0;i<12;i++)jobs.add(()->{var c=new AiCostProtection(jdbc,goals,manager,env);try{run(c,1,"DAILY_COACHING",a,k);return 200;}catch(AiCostFailure e){return e.status;}});for(var f:pool.invokeAll(jobs))assertTrue(Set.of(200,409).contains(f.get()));assertEquals(1,sends.get());assertEquals(1,rows());}finally{pool.shutdownNow();}}
 @Test void inFlightNewKeyAndSecondGoalCannotDispatch()throws Exception{String k=key();var began=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newSingleThreadExecutor();try{var task=pool.submit(()->cost.execute(1,"DAILY_COACHING",a,"gemini",MODEL,k,"POST",body(),()->{cost.beforeSend("synthetic");began.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(Exception e){throw new RuntimeException();}sends.incrementAndGet();return new LinkedHashMap<>(Map.of("goalId",a,"provider","gemini","model",MODEL,"responseModel",MODEL,"responseSource","provider","llmResponse","FakeWire"));}));assertTrue(began.await(3,TimeUnit.SECONDS));assertEquals(409,assertThrows(AiCostFailure.class,()->run(cost,1,"DAILY_COACHING",b,key())).status);release.countDown();task.get(5,TimeUnit.SECONDS);assertEquals(1,sends.get());}finally{release.countDown();pool.shutdownNow();}}
 @Test void anotherUserMayUseSameKeyWithoutSeeingOwnerResult(){jdbc.update("INSERT INTO users(user_id,name) VALUES(2,'synthetic other')");var g=new Goal();g.setUserId(2L);long other=goals.saveAndFlush(g).getGoalId();try{String k=key();run(cost,1,"DAILY_COACHING",a,k);run(cost,2,"DAILY_COACHING",other,k);assertEquals(2,sends.get());assertEquals(2,rows());assertEquals("NOT_CONFIRMED",cost.lookup(2,"STUDY_SUMMARY",other,k).get("state"));}finally{jdbc.update("DELETE FROM ai_generation_requests WHERE user_id=2");goals.deleteById(other);jdbc.update("DELETE FROM users WHERE user_id=2");}}
 @Test void beforeProviderFailureIsNoSendAndNeverReexecuted(){String k=key();var result=cost.execute(1,"DAILY_COACHING",a,"gemini",MODEL,k,"POST",body(),()->{throw new IllegalStateException("synthetic failure");});assertEquals("NO_SEND",((Map<?,?>)result.get("costProtection")).get("state"));run(cost,1,"DAILY_COACHING",a,k);assertEquals(0,sends.get());}
 @Test void timeoutAfterDispatchPersistsUnknownAndBlocksNewRequest()throws Exception{when(wire.send(any(HttpRequest.class),any(HttpResponse.BodyHandler.class))).thenAnswer(i->{sends.incrementAndGet();throw new HttpTimeoutException("synthetic");});String k=key();var r=generate("/llm-coaching",a,k);assertEquals("UNKNOWN",tree(r).at("/costProtection/state").asText());assertEquals(409,generate("/llm-coaching",a,key()).getResponse().getStatus());assertEquals(1,sends.get());assertEquals("UNKNOWN",tree(lookup("DAILY_COACHING",a,k)).path("state").asText());}
 @Test void providerAnswerAndAiResponseSaveFailureAreDifferent()throws Exception{var failing=mock(AiResponseService.class);when(failing.save(any(),any(),any(),any(),any(),any(),any(),any(),any())).thenThrow(new IllegalStateException("synthetic"));ReflectionTestUtils.setField(ctx.getBean(LlmCoachingController.class),"responseRecorder",new AiResponseRecorder(failing));String k=key();var r=generate("/llm-coaching",a,k);assertEquals("COMPLETED",tree(r).at("/costProtection/state").asText());assertFalse(tree(r).path("responseSaved").asBoolean());assertTrue(tree(r).at("/costProtection/resultStored").asBoolean());assertEquals(0,responses.count());lookup("DAILY_COACHING",a,k);assertEquals(1,sends.get());}
 @Test void resultLedgerFailureAfterDispatchStaysReservedAcrossRecreation(){var failing=new AiCostProtection(jdbc,goals,manager,env){protected void beforeResultStore(){throw new IllegalStateException("synthetic");}};String k=key();assertEquals(503,assertThrows(AiCostFailure.class,()->run(failing,1,"DAILY_COACHING",a,k)).status);var fresh=new AiCostProtection(jdbc,goals,manager,env);assertEquals("DISPATCH_RESERVED",fresh.lookup(1,"DAILY_COACHING",a,k).get("state"));assertEquals(409,assertThrows(AiCostFailure.class,()->run(fresh,1,"DAILY_COACHING",a,k)).status);assertEquals(1,sends.get());}
